def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        if line[i] == '"':
            # Quoted field
            field = []
            i += 1  # Skip opening quote
            while i < len(line):
                if line[i] == '"':
                    if i + 1 < len(line) and line[i + 1] == '"':
                        # Doubled quote - represents one quote
                        field.append('"')
                        i += 2
                    else:
                        # Closing quote
                        i += 1
                        # Check what follows
                        if i < len(line):
                            if line[i] == ',':
                                i += 1
                                fields.append(''.join(field))
                                break
                            else:
                                # Invalid: closing quote not followed by comma or end
                                return None
                        else:
                            # End of line - valid
                            fields.append(''.join(field))
                            break
                else:
                    field.append(line[i])
                    i += 1
            else:
                # Reached end of line without finding closing quote
                return None
        else:
            # Unquoted field
            field = []
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Double quote not allowed in unquoted field
                    return None
                field.append(line[i])
                i += 1

            fields.append(''.join(field))

            if i < len(line):
                # Skip comma
                i += 1

    return fields

